from pathlib import Path


def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f'{label}: target not found')
    if text.count(old) != 1:
        raise SystemExit(f'{label}: expected one target, found {text.count(old)}')
    return text.replace(old, new, 1)

p = Path('admin/admin.js')
s = p.read_text(encoding='utf-8')

old_color_row = '''      return `<div class="color-image-row">\n        <div class="color-image-preview">${selected ? `<img src="${esc(selected)}" alt="${esc(color)}">` : '<span>Нет фото</span>'}</div>\n        <div class="color-image-meta"><b>${esc(color)}</b><small>Фото при выборе этого цвета</small></div>\n        <select data-color-image-select="${esc(color)}">${options}</select>\n      </div>`;'''
new_color_row = '''      return `<div class="color-image-row">\n        <div class="color-image-preview">${selected ? `<img src="${esc(selected)}" alt="${esc(color)}">` : '<span>Нет фото</span>'}</div>\n        <div class="color-image-meta"><b>${esc(color)}</b><small>Фото при выборе этого цвета</small></div>\n        <div class="color-image-controls">\n          <select data-color-image-select="${esc(color)}">${options}</select>\n          ${selected ? `<button type="button" class="color-image-delete" data-color-image-remove="${esc(color)}">Удалить фото</button>` : ''}\n        </div>\n      </div>`;'''
